update sskr_private.places set document='{"id":"sokcho","kind":"start","name":"속초해수욕장","region":"강원 · 속초","lat":38.18743167,"lng":128.6052197,"lead":"설악과 동해를 곁에 둔 북쪽 출발점.","description":"동해의 백사장과 설악산을 가까이서 만나는 해변입니다. 해안을 따라 남하하거나 강원 내륙으로 향하는 출발점입니다.","note":"","source":"https://sokcho.go.kr/sc/fields/traffic/parking","image":"/web/app/assets/spots/sokcho.webp","photoCredit":"Grapesurgeon · CC BY-SA 4.0 · WebP 변환·축소","coordinateAccuracy":"parking-osm","photoSource":"https://commons.wikimedia.org/wiki/File:Sokcho_Beach_01.jpg","category":"nature","visitCoordinate":[38.18743167,128.6052197],"parking":{"lat":38.18743167,"lng":128.6052197,"osm":"https://www.openstreetmap.org/way/178808349","distanceToPlaceMeters":83,"evidence":"속초시 해수욕장 공영주차장 목록과 OSM amenity=parking; 이륜차 도로 접근 확인 2026-09-28"},"photoOriginalUrl":"https://upload.wikimedia.org/wikipedia/commons/2/28/Sokcho_Beach_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","photoChanges":"WebP 변환 및 960px 이내 축소","photoKind":"PLACE_PHOTO","photoVerifiedAt":"2026-10-04","reuseStatus":"verified","address":"강원특별자치도 속초시 해오름로 186","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=12e3b8dc-81ad-44e7-87af-ffd9adb412d6","addressVerifiedAt":"2026-10-16","operatorNote":"속초해수욕장 주차장 후보 · 행사 집결과 이륜차 주차 가능 구획은 운영 주체와 확인"}'::jsonb where id='sokcho';
