update sskr_private.places set document='{"id":"mangsang","kind":"start","name":"망상해변","region":"강원 · 동해","lat":37.592269,"lng":129.089671,"lead":"긴 백사장과 솔숲 앞에서 여는 하루.","description":"강릉과 삼척 사이의 동해안 출발점입니다.","note":"","source":"https://access.visitkorea.or.kr/opentour/detail.do?cotId=561aff08-da51-4e3b-a2c1-9a141973f590","image":"https://access.visitkorea.or.kr/bfvk_img/call?cmd=VIEW&id=1f0231b3-d52e-431a-ac1c-171a8e91eef1","photoCredit":"사진 · 한국관광공사","coordinateAccuracy":"approximate","category":"nature","address":"강원특별자치도 동해시 동해대로 6270-10","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=46a1d5f9-c4f9-434b-879a-2d3f02330709","addressVerifiedAt":"2026-10-16","operatorNote":"해변 공영주차장 후보 · 실제 집결 구획과 행사 사용 협의 필요"}'::jsonb where id='mangsang';
update sskr_private.places set document='{"id":"samcheok","kind":"start","name":"맹방해수욕장","region":"강원 · 삼척","lat":37.389,"lng":129.232,"lead":"긴 백사장을 마주하며 하루의 횡단을 시작합니다.","description":"넓게 이어지는 백사장과 덕봉산이 삼척의 해안 풍경을 만듭니다.","note":"","source":"https://www.samcheok.go.kr/tour.web","image":"https://tong.visitkorea.or.kr/cms/resource/79/1813179_image2_1.jpg","photoCredit":"사진 · 한국관광공사 / 원문 출처 확인","coordinateAccuracy":"approximate","category":"nature","address":"강원특별자치도 삼척시 근덕면 맹방해변로 228-239","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=14d6a401-0253-408e-8d07-a213ee18355c","addressVerifiedAt":"2026-10-16","operatorNote":"해수욕장 주차장 후보 · 성수기 혼잡 및 행사 사용 확인"}'::jsonb where id='samcheok';
update sskr_private.places set document='{"id":"uljin","kind":"start","name":"망양정해수욕장","region":"경북 · 울진","lat":36.97,"lng":129.416,"lead":"왕피천이 동해에 닿는 곳에서 시작합니다.","description":"왕피천 하구와 망양정 아래 펼쳐진 해변입니다. 불영계곡과 봉화 방향으로 향하는 중부 횡단의 출발 후보입니다.","note":"","source":"https://www.uljin.go.kr/board/view.uljin?boardId=BBS_ATTRACTION_TU&dataSid=1664","image":"https://www.uljin.go.kr/upload_data/board_data/BBS_ATTRACTION_TU/173923364455613.jpg","photoCredit":"사진 · 울진군","coordinateAccuracy":"approximate","category":"nature","address":"경상북도 울진군 근남면 망양정로 1016","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=abefc49c-cd1f-4f68-a6fe-2e7aa0c065fd","addressVerifiedAt":"2026-10-16","operatorNote":"해변 주차장 후보 · 진출입 동선과 집결 허가 확인"}'::jsonb where id='uljin';
update sskr_private.places set document='{"id":"yeongdeok","kind":"start","name":"고래불해수욕장","region":"경북 · 영덕","lat":36.602,"lng":129.41,"lead":"고래불의 긴 해안, 남쪽에서 시작하는 하루.","description":"길게 이어진 백사장과 소나무 숲이 있는 영덕의 해변입니다. 병곡의 바다에서 청송 방면 내륙으로 이어갈 수 있습니다.","note":"","source":"https://access.visitkorea.or.kr/opentour/detail.do?cotId=9b7101c9-7965-42b6-b00a-ad2513e8d9ac","image":"https://access.visitkorea.or.kr/bfvk_img/call?cmd=VIEW&id=98c9ee51-a79b-4750-a826-dfbd2dd4870a","photoCredit":"사진 · 영덕군 / 한국관광공사","coordinateAccuracy":"approximate","category":"nature","address":"경상북도 영덕군 병곡면 병곡리","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=9d8c47a4-a3c1-4273-80a8-33f07a65c1f5","addressVerifiedAt":"2026-10-16","operatorNote":"병곡 해변 광장·주차장 후보 · 축제 일정 및 대관 확인"}'::jsonb where id='yeongdeok';
