update sskr_private.places set document='{"id":"gyeongju","kind":"start","name":"읍천항 · 파도소리길","region":"경북 · 경주","lat":35.692,"lng":129.475,"lead":"주상절리의 바다를 곁에 두고 출발합니다.","description":"읍천항과 양남 주상절리 파도소리길이 가까운 출발점입니다. 항구와 해안 바위를 함께 둘러볼 수 있습니다.","note":"","source":"https://www.gyeongju.go.kr/tour/page.do?mnu_uid=3621","image":"https://www.gyeongju.go.kr/design/tour2019/img/sub/tMonth_2024/20241128-41.jpg","photoCredit":"사진 · 경주시, 공공누리 제1유형 (주상절리 파도소리길)","coordinateAccuracy":"approximate","category":"nature","address":"경상북도 경주시 양남면 양남항구길 46","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=88da1cc3-e5c1-45d1-af29-5e31d025df4a","addressVerifiedAt":"2026-10-16","operatorNote":"읍천항 공용주차장 후보 · 어항 작업 및 주민 동선 우선"}'::jsonb where id='gyeongju';
update sskr_private.places set document='{"id":"jinha","kind":"start","name":"진하해수욕장","region":"울산 · 울주","lat":35.383522,"lng":129.346011,"lead":"명선도 앞 새벽 바다에서 출발합니다.","description":"경주와 부산 사이의 울주 출발점입니다.","note":"","source":"https://www.ulsan.go.kr/tour/kor/unit/attrctn/view.do?mId=001002001000000000&unqId=16","image":"/web/app/assets/spots/jinha.webp","photoCredit":"Jh Jung · CC BY 3.0 · WebP 변환·축소","coordinateAccuracy":"approximate","photoSource":"https://commons.wikimedia.org/wiki/File:Sunrise_(169520597).jpeg","category":"nature","photoOriginalUrl":"https://upload.wikimedia.org/wikipedia/commons/b/bc/Sunrise_%28169520597%29.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","photoLicense":"CC BY 3.0","photoLicenseUrl":"https://creativecommons.org/licenses/by/3.0","photoChanges":"WebP 변환 및 960px 이내 축소","photoKind":"PLACE_PHOTO","photoVerifiedAt":"2026-10-04","reuseStatus":"verified","address":"울산광역시 울주군 서생면 진하해변길 77","addressSource":"https://access.visitkorea.or.kr/common/goDetail.do?cotId=849cd59b-1cf5-458c-99c6-d6564ad00345","addressVerifiedAt":"2026-10-16","operatorNote":"진하 공영주차장 후보 · 새벽 집결 사용, 주차 구획과 진출입 협의 필요"}'::jsonb where id='jinha';
update sskr_private.places set document='{"id":"gwangalli","kind":"start","name":"광안리해수욕장","region":"부산 · 수영","lat":35.153813,"lng":129.118548,"lead":"광안대교와 바다가 함께 보이는 도심 출발점.","description":"광안리해수욕장은 부산 도심에서 바다를 만나는 곳입니다.","note":"","source":"https://data.visitkorea.or.kr/linkedview/126078","image":"/web/app/assets/spots/gwangalli.webp","photoCredit":"VN.NguyenDucDuy · CC BY-SA 4.0 · WebP 변환·축소","coordinateAccuracy":"approximate","photoSource":"https://commons.wikimedia.org/wiki/File:Sunrise_at_Gwangalli_Beach,_Busan.jpg","category":"nature","photoOriginalUrl":"https://upload.wikimedia.org/wikipedia/commons/6/6f/Sunrise_at_Gwangalli_Beach%2C_Busan.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","photoLicense":"CC BY-SA 4.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","photoChanges":"WebP 변환 및 960px 이내 축소","photoKind":"PLACE_PHOTO","photoVerifiedAt":"2026-10-04","reuseStatus":"verified","address":"부산광역시 수영구 광안해변로 219 (광안동)","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=98763dd6-119d-4e32-910e-a40652334bda","addressVerifiedAt":"2026-10-16","operatorNote":"인근 공영주차장 후보 · 새벽 집결 동선과 행사 사용 협의 필요"}'::jsonb where id='gwangalli';
update sskr_private.places set document='{"id":"songjeong","kind":"start","name":"송정해수욕장","region":"부산 · 해운대","lat":35.178712,"lng":129.19964,"lead":"송정의 바다에서 남부 횡단을 시작합니다.","description":"송정해수욕장과 죽도 인근에서 아침 바다를 만나는 출발점입니다.","note":"","source":"https://data.visitkorea.or.kr/linkedview/126080","image":"/web/app/assets/spots/songjeong.webp","photoCredit":"Andrewssi2 · CC BY-SA 3.0 · WebP 변환·축소","coordinateAccuracy":"approximate","photoSource":"https://commons.wikimedia.org/wiki/File:Songjeong_Beach.jpg","category":"nature","photoOriginalUrl":"https://upload.wikimedia.org/wikipedia/commons/a/ad/Songjeong_Beach.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","photoLicense":"CC BY-SA 3.0","photoLicenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","photoChanges":"WebP 변환 및 960px 이내 축소","photoKind":"PLACE_PHOTO","photoVerifiedAt":"2026-10-04","reuseStatus":"verified","address":"부산광역시 해운대구 송정동 712-2","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=b0136743-e02d-4f1b-bef6-cc1b63536489","addressVerifiedAt":"2026-10-16","operatorNote":"송정해변 주차장 후보 · 성수기 혼잡과 집결 허가 확인"}'::jsonb where id='songjeong';
update sskr_private.places set document='{"id":"auraji","kind":"spot","name":"아우라지","region":"강원 · 정선","lat":37.4766764,"lng":128.7219016,"lead":"두 물줄기와 정선 아리랑이 만나는 자리.","description":"송천과 골지천이 합류하는 물가에서 정선의 지형과 이야기를 만납니다. 강변을 걷는 짧은 휴식으로 산간 구간의 리듬을 바꿔보세요.","note":"","source":"https://data.visitkorea.or.kr/linkedview/125777","image":"https://tong.visitkorea.or.kr/cms/resource/41/2395941_image2_1.jpg","photoCredit":"사진 · 한국관광공사 / 원문 출처 확인","coordinateAccuracy":"parking-osm","category":"nature","visitCoordinate":[37.483,128.721],"parking":{"lat":37.4766764,"lng":128.7219016,"osm":"https://www.openstreetmap.org/way/1196258522","distanceToPlaceMeters":708,"evidence":"OSM amenity=parking, access not restricted, motorcycle road snap verified 2026-09-28"},"address":"강원특별자치도 정선군 여량면 아우라지길 69","addressSource":"https://korean.visitkorea.or.kr/detail/ms_detail.do?cotid=2dcf87bf-c35c-450f-93e9-8d7ec4fd8564","addressVerifiedAt":"2026-10-16","operatorNote":"강변 공용 주차 구역 이용 · 산책로 보행"}'::jsonb where id='auraji';
update sskr_private.places set document='{"id":"cheongnyeongpo","kind":"spot","name":"청령포","region":"강원 · 영월","lat":37.1787948,"lng":128.4456095,"lead":"소나무 숲에 남은 단종의 시간.","description":"삼면을 감싸는 강과 소나무 숲이 고요한 풍경을 이루는 단종 유배지입니다. 강 건너 방문에는 별도의 관람 시간이 필요합니다.","note":"배를 타고 들어가는 관람 코스입니다.","source":"https://data.visitkorea.or.kr/linkedview/125785","image":"https://tong.visitkorea.or.kr/cms/resource/60/2517660_image2_1.jpg","photoCredit":"사진 · 한국관광공사 / 원문 출처 확인","coordinateAccuracy":"parking-osm","category":"culture","visitCoordinate":[37.178,128.446],"parking":{"lat":37.1787948,"lng":128.4456095,"osm":"https://www.openstreetmap.org/way/1256468454","distanceToPlaceMeters":95,"evidence":"OSM amenity=parking, access not restricted, motorcycle road snap verified 2026-09-28"},"address":"강원특별자치도 영월군 남면 광천리 산67-1","addressSource":"https://access.visitkorea.or.kr/ms/detail.do?cotId=041c4a30-70fd-48ad-b5e0-98e7f753908d","addressVerifiedAt":"2026-10-16","operatorNote":"주차 후 매표·도선 이용 · 운항 및 입장 여부 확인"}'::jsonb where id='cheongnyeongpo';
