create or replace function sskr_private.event_document(p_document jsonb) returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare
  doc jsonb;
  field text;
  entry jsonb;
begin
  if p_document is null or jsonb_typeof(p_document) <> 'object' or octet_length(p_document::text) > 1048576
    or exists(select 1 from jsonb_object_keys(p_document) k where k not in (
      'publicTitle','editionLabel','description','timezone','eventStartAt','eventEndAt',
      'applicationOpenAt','applicationCloseAt','minimumSpotCheckins','startLocationIds',
      'finishLocationId','sunlight','coreConfirmedAt','spotsConfirmedAt','isTest','timeMode','placeCatalog','catalogVersion','routingVersion'))
  then raise exception 'INVALID_EVENT'; end if;
  doc := jsonb_build_object('timezone','Asia/Seoul','minimumSpotCheckins',10,
    'finishLocationId','daecheon','startLocationIds','[]'::jsonb) || p_document;
  if doc->>'timezone' is distinct from 'Asia/Seoul' or (coalesce(doc->>'')='' and doc->>'finishLocationId' is distinct from 'daecheon')
    or jsonb_typeof(doc->'minimumSpotCheckins') is distinct from 'number'
    or (doc->>'minimumSpotCheckins') !~ '^[0-9]{1,3}$'
  then raise exception 'INVALID_EVENT'; end if;
  if (doc->>'minimumSpotCheckins')::integer not between 1 and 200 then raise exception 'INVALID_EVENT'; end if;
  foreach field in array array['publicTitle','editionLabel','description'] loop
    if doc ? field and (jsonb_typeof(doc->field) <> 'string'
      or length(doc->>field) > case when field='description' then 4000 when field='publicTitle' then 120 else 80 end)
    then raise exception 'INVALID_EVENT'; end if;
  end loop;
  foreach field in array array['eventStartAt','eventEndAt','applicationOpenAt','applicationCloseAt','coreConfirmedAt','spotsConfirmedAt'] loop
    if doc ? field and doc->field <> 'null'::jsonb then
      if jsonb_typeof(doc->field) <> 'string' then raise exception 'INVALID_EVENT'; end if;
      perform sskr_private.event_timestamp(doc->>field);
    end if;
  end loop;
  if jsonb_typeof(doc->'startLocationIds') is distinct from 'array' then raise exception 'INVALID_EVENT'; end if;
  if jsonb_array_length(doc->'startLocationIds') > 50
    or exists(select 1 from jsonb_array_elements(doc->'startLocationIds') x where jsonb_typeof(x) <> 'string')
    or (select count(*) <> count(distinct x) from jsonb_array_elements_text(doc->'startLocationIds') x)
  then raise exception 'INVALID_EVENT'; end if;
  if doc ? 'isTest' and jsonb_typeof(doc->'isTest')<>'boolean' then raise exception 'INVALID_EVENT'; end if;
  if (coalesce(doc->>'')<>'' or doc->>'timeMode'='MANUAL') and coalesce(doc->>'isTest','false')<>'true' then raise exception 'INVALID_EVENT'; end if;
  if coalesce(doc->>'timeMode','SOLAR') not in ('SOLAR','MANUAL') then raise exception 'INVALID_EVENT'; end if;
  if doc->>'isTest'='true' then
    if exists(select 1 from jsonb_array_elements_text(doc->'startLocationIds') x where not exists(
        select 1 from sskr_private.field_places p where p.id=x and p.document->>'startEligible'='true') and not exists(
        select 1 from sskr_private.places p where p.id=x and p.kind='start' and p.active))
      or not (doc->>'finishLocationId'='daecheon' or exists(select 1 from sskr_private.field_places p where p.id=doc->>'finishLocationId' and p.document->>'kind'='spot'))
      or (doc->'startLocationIds') ? (doc->>'finishLocationId')
    then raise exception 'INVALID_EVENT'; end if;
    doc:=doc || jsonb_build_object('placeCatalog',(
      select jsonb_agg(p.document || jsonb_build_object('kind',case when p.id=doc->>'finishLocationId' then 'finish'
        when (doc->'startLocationIds') ? p.id then 'start' when p.document->>'kind'='finish' then 'inactive' else p.document->>'kind' end) order by p.catalog_order,p.id)
      from (select id,document,catalog_order from sskr_private.places where active union all select id,document||jsonb_build_object(
        'region',case when document->>'group'='bus110a' then '서울' else '경기' end,'category','nature','lead',document->>'name'),10000 from sskr_private.field_places) p));
    doc:=doc || jsonb_build_object('catalogVersion','places-'||md5((doc->'placeCatalog')::text),'routingVersion','c24f0f88f894360d4653+184de091c11c8690e2e2');
  else
    if doc->>'finishLocationId' is distinct from 'daecheon' or exists(select 1 from jsonb_array_elements_text(doc->'startLocationIds') x where not exists(
      select 1 from sskr_private.places p where p.id=x and p.kind='start' and p.active))
    then raise exception 'INVALID_EVENT'; end if;
    doc:=doc - array['placeCatalog','catalogVersion','routingVersion'];
  end if;
  if doc->>'timeMode'='MANUAL' then doc:=doc || jsonb_build_object('sunlight',null); end if;
  if doc ? 'sunlight' and doc->'sunlight' <> 'null'::jsonb then
    if jsonb_typeof(doc->'sunlight') <> 'object' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    if exists(select 1 from jsonb_object_keys(doc->'sunlight') k where k not in
      ('eventId','date','timezone','configVersion','verification','sourceUrl','calculationVersion','starts','finish'))
    then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    foreach field in array array['eventId','date','timezone','verification','sourceUrl','calculationVersion'] loop
      if (doc->'sunlight') ? field and jsonb_typeof(doc#>array['sunlight',field]) <> 'string' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    end loop;
    if (doc->'sunlight') ? 'configVersion' and jsonb_typeof(doc#>'{sunlight,configVersion}') <> 'number' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    if (doc->'sunlight') ? 'starts' then
      if jsonb_typeof(doc#>'{sunlight,starts}') <> 'array' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
      if jsonb_array_length(doc#>'{sunlight,starts}') > 50 then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    end if;
    if (doc->'sunlight') ? 'finish' and jsonb_typeof(doc#>'{sunlight,finish}') <> 'object' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    for entry in select value from jsonb_array_elements(coalesce(doc#>'{sunlight,starts}','[]'::jsonb))
      union all select doc#>'{sunlight,finish}' where (doc->'sunlight') ? 'finish'
    loop
      if jsonb_typeof(entry) <> 'object' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
      if exists(select 1 from jsonb_object_keys(entry) k where k not in ('locationId','lat','lng','sunriseAt','sunsetAt')) then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
      foreach field in array array['locationId','sunriseAt','sunsetAt'] loop
        if entry ? field and jsonb_typeof(entry->field) <> 'string' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
      end loop;
      foreach field in array array['lat','lng'] loop
        if entry ? field then
          if jsonb_typeof(entry->field) <> 'number' then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
          if abs((entry->>field)::numeric) > (case when field='lat' then 90 else 180 end) then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
        end if;
      end loop;
    end loop;
  end if;
  return doc;
end $$;

create or replace function sskr_private.validate_event_publication(p_id uuid, p_version bigint, p_document jsonb) returns void
language plpgsql security invoker set search_path = '' as $$
declare
  doc jsonb := sskr_private.event_document(p_document);
  light jsonb := doc->'sunlight';
  entry jsonb;
  finish jsonb;
  starts timestamptz;
  ends timestamptz;
  sunrise timestamptz;
  sunset timestamptz;
  local_date text;
begin
  if length(btrim(coalesce(doc->>'publicTitle',''))) = 0
    or doc->>'eventStartAt' is null or doc->>'eventEndAt' is null
    or jsonb_array_length(doc->'startLocationIds') = 0
  then raise exception 'INVALID_EVENT'; end if;
  starts := sskr_private.event_timestamp(doc->>'eventStartAt');
  ends := sskr_private.event_timestamp(doc->>'eventEndAt');
  local_date := to_char(starts at time zone 'Asia/Seoul','YYYY-MM-DD');
  if starts >= ends or local_date <> to_char(ends at time zone 'Asia/Seoul','YYYY-MM-DD') then raise exception 'INVALID_EVENT'; end if;
  if doc->>'applicationOpenAt' is not null and doc->>'applicationCloseAt' is not null
    and sskr_private.event_timestamp(doc->>'applicationOpenAt') >= sskr_private.event_timestamp(doc->>'applicationCloseAt')
  then raise exception 'INVALID_EVENT'; end if;
  if doc->>'timeMode'='MANUAL' then return; end if;
  if jsonb_typeof(light) is distinct from 'object'
    or light->>'eventId' is distinct from p_id::text
    or light->>'date' is distinct from local_date
    or light->>'timezone' is distinct from 'Asia/Seoul'
    or light->'configVersion' is distinct from to_jsonb(p_version)
    or light->>'verification' is distinct from 'REVIEWED'
    or jsonb_typeof(light->'sourceUrl') is distinct from 'string'
    or coalesce(light->>'sourceUrl','') !~ '^https://[^[:space:]]+$'
    or jsonb_typeof(light->'calculationVersion') is distinct from 'string'
    or length(btrim(coalesce(light->>'calculationVersion',''))) not between 1 and 120
    or jsonb_typeof(light->'starts') is distinct from 'array'
    or jsonb_typeof(light->'finish') is distinct from 'object'
  then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  if jsonb_array_length(light->'starts') <> jsonb_array_length(doc->'startLocationIds')
    or (select count(*) <> count(distinct x->>'locationId') from jsonb_array_elements(light->'starts') x)
  then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  finish := light->'finish';
  if finish->>'locationId' is distinct from doc->>'finishLocationId'
    or jsonb_typeof(finish->'lat') is distinct from 'number' or jsonb_typeof(finish->'lng') is distinct from 'number'
  then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  if (finish->>'lat')::numeric not between -90 and 90 or (finish->>'lng')::numeric not between -180 and 180 then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  if not exists(select 1 from sskr_private.places where id=finish->>'locationId' and active and kind='finish'
    and lat=(finish->>'lat')::numeric and lng=(finish->>'lng')::numeric) then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  begin
    sunset := sskr_private.event_timestamp(finish->>'sunsetAt');
  exception when others then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end;
  if to_char(sunset at time zone 'Asia/Seoul','YYYY-MM-DD') <> local_date then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  for entry in select value from jsonb_array_elements(light->'starts') loop
    if jsonb_typeof(entry) <> 'object' or not (doc->'startLocationIds') ? coalesce(entry->>'locationId','')
      or jsonb_typeof(entry->'lat') is distinct from 'number' or jsonb_typeof(entry->'lng') is distinct from 'number'
    then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    if (entry->>'lat')::numeric not between -90 and 90 or (entry->>'lng')::numeric not between -180 and 180 then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    if not exists(select 1 from sskr_private.places where id=entry->>'locationId' and active and kind='start'
      and lat=(entry->>'lat')::numeric and lng=(entry->>'lng')::numeric) then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
    begin
      sunrise := sskr_private.event_timestamp(entry->>'sunriseAt');
    exception when others then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end;
    if sunrise >= sunset or to_char(sunrise at time zone 'Asia/Seoul','YYYY-MM-DD') <> local_date then raise exception 'SUNLIGHT_REVIEW_REQUIRED'; end if;
  end loop;
end $$;

create or replace function sskr_private.routes_api(
  p_action text, p_id uuid default null, p_plan jsonb default null,
  p_schedule jsonb default null, p_revision bigint default null, p_key text default null
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  actor_id uuid := sskr_private.actor();
  cfg sskr_private.settings;
  existing sskr_private.routes;
  previous sskr_private.route_requests;
  result jsonb;
  route_id uuid := coalesce(p_id, gen_random_uuid());
  stamp timestamptz := clock_timestamp();
  active_event jsonb := sskr_private.public_event();
  doc jsonb; agenda jsonb; route_title text; next_number integer := 1;
  payload jsonb := jsonb_build_object('plan',p_plan,'schedule',p_schedule);
begin
  select * into strict cfg from sskr_private.settings where singleton;
  if active_event->>'isTest'='true' then
    cfg.finish_id:=active_event->>'finishLocationId';
    cfg.catalog_version:=active_event->>'catalogVersion';
    cfg.routing_version:=active_event->>'routingVersion';
  end if;
  if p_action = 'list' then
    return jsonb_build_object('maxSavedRoutes',cfg.max_saved_routes,'routes',coalesce((
      select jsonb_agg(jsonb_build_object('plan',plan,'schedule',schedule,'revision',revision) order by updated_at desc,id)
      from sskr_private.routes where owner_id=actor_id), '[]'::jsonb));
  end if;
  if p_action not in ('save','schedule','delete') then raise exception 'INVALID_ACTION'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor_id::text, 7391));
  if p_id is not null then
    select * into existing from sskr_private.routes where id=p_id and owner_id=actor_id;
    if not found then raise exception 'ROUTE_NOT_FOUND'; end if;
    if p_revision is null then raise exception 'REVISION_REQUIRED'; end if;
    if p_revision <> existing.revision then raise exception 'REVISION_CONFLICT'; end if;
  elsif p_action <> 'save' then raise exception 'ROUTE_NOT_FOUND';
  else
    if p_key is null or length(p_key) < 16 or length(p_key) > 128 then raise exception 'IDEMPOTENCY_REQUIRED'; end if;
    select * into previous from sskr_private.route_requests where owner_id=actor_id and request_key=p_key;
    if found then
      if previous.payload <> payload then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
      return previous.response;
    end if;
    if (select count(*) from sskr_private.routes where owner_id=actor_id) >= cfg.max_saved_routes then raise exception 'ROUTE_LIMIT_REACHED'; end if;
  end if;
  if p_action = 'delete' then
    delete from sskr_private.routes where id=p_id and owner_id=actor_id;
    return jsonb_build_object('deleted',p_id);
  end if;
  agenda := p_schedule;
  if agenda is null or jsonb_typeof(agenda) <> 'object'
    or (coalesce(agenda->>'departureTime','') <> '' and agenda->>'departureTime' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
    or coalesce(agenda->>'breakMinutes','') !~ '^[0-9]{1,4}$'
    or (agenda->>'breakMinutes')::integer > 1440
    or jsonb_typeof(agenda->'autoDeparture') is distinct from 'boolean'
  then raise exception 'INVALID_SCHEDULE'; end if;
  -- Event metadata is server-owned. The first release has no published event.
  agenda := jsonb_build_object('departureTime',agenda->>'departureTime','breakMinutes',(agenda->>'breakMinutes')::integer,
    'autoDeparture',agenda->'autoDeparture','eventId',null,'configVersion',null,'timezone','Asia/Seoul');
  if p_action = 'schedule' then
    update sskr_private.routes set schedule=agenda, revision=revision+1, updated_at=stamp,
      plan=jsonb_set(plan,'{updatedAt}',to_jsonb(stamp)) where id=p_id and owner_id=actor_id
      returning jsonb_build_object('plan',plan,'schedule',schedule,'revision',revision) into result;
    return result;
  end if;
  if p_plan is null or jsonb_typeof(p_plan) <> 'object'
    or jsonb_typeof(p_plan->'stopIds') is distinct from 'array'
    or jsonb_typeof(coalesce(p_plan->'pinnedStopIds','[]')) <> 'array'
    or jsonb_array_length(p_plan->'stopIds') > 200
    or length(coalesce(p_plan->>'title','')) > 60
    or coalesce(p_plan->>'finishId','') <> cfg.finish_id
  then raise exception 'INVALID_PLAN'; end if;
  if p_plan->>'startId' is not null and not (case when active_event->>'isTest'='true' then (active_event->'startLocationIds') ? (p_plan->>'startId') else exists(select 1 from sskr_private.places where id=p_plan->>'startId' and kind='start' and active) end) then raise exception 'INVALID_REFERENCE'; end if;
  if exists(select 1 from jsonb_array_elements_text(p_plan->'stopIds') x where not (case when active_event->>'isTest'='true' then exists(select 1 from jsonb_array_elements(active_event->'placeCatalog') p where p->>'id'=x and p->>'kind'='spot') else exists(select 1 from sskr_private.places where id=x and kind='spot' and active) end))
    or (select count(*)<>count(distinct x) from jsonb_array_elements_text(p_plan->'stopIds') x)
    or exists(select 1 from jsonb_array_elements_text(coalesce(p_plan->'pinnedStopIds','[]')) x where not (p_plan->'stopIds') ? x)
    or (select count(*)<>count(distinct x) from jsonb_array_elements_text(coalesce(p_plan->'pinnedStopIds','[]')) x)
  then raise exception 'INVALID_REFERENCE'; end if;
  if coalesce(p_plan->>'catalogVersion','') <> cfg.catalog_version or (coalesce(p_plan->>'routingVersion','') <> cfg.routing_version and (p_plan->>'routingVersion' is not null or jsonb_array_length(p_plan->'stopIds')>0)) then raise exception 'CATALOG_CHANGED'; end if;
  route_title := btrim(coalesce(p_plan->>'title',''));
  if route_title = '' then
    while exists(select 1 from sskr_private.routes where owner_id=actor_id and
      (regexp_match(plan->>'title', '^루트\s+0*([0-9]+)$'))[1] = next_number::text)
    loop next_number := next_number+1; end loop;
    route_title := '루트 ' || case when next_number < 10 then '0' else '' end || next_number::text;
  end if;
  doc := jsonb_build_object('id',route_id::text,'ownerUserId',actor_id::text,'title',route_title,
    'startId',p_plan->'startId','stopIds',p_plan->'stopIds','pinnedStopIds',coalesce(p_plan->'pinnedStopIds','[]'),
    'finishId',cfg.finish_id,'catalogVersion',cfg.catalog_version,'routingVersion',cfg.routing_version,
    'createdAt',coalesce(existing.created_at,stamp),'updatedAt',stamp);
  insert into sskr_private.routes(id,owner_id,plan,schedule,revision,created_at,updated_at)
    values(route_id,actor_id,doc,agenda,coalesce(existing.revision,0)+1,coalesce(existing.created_at,stamp),stamp)
    on conflict(id) do update set plan=excluded.plan,schedule=excluded.schedule,revision=excluded.revision,updated_at=excluded.updated_at
    returning jsonb_build_object('plan',plan,'schedule',schedule,'revision',revision) into result;
  if p_id is null then insert into sskr_private.route_requests(owner_id,request_key,payload,response) values(actor_id,p_key,payload,result); end if;
  return result;
end $$;

create function public.sskr_event_place_options() returns jsonb language plpgsql security definer set search_path='' as $$
begin
  if not exists(select 1 from sskr_private.event_operators where user_id=sskr_private.actor()) then raise exception 'FORBIDDEN'; end if;
  return (select coalesce(jsonb_agg(document order by id),'[]'::jsonb) from sskr_private.field_places);
end $$;
revoke all on function public.sskr_event_place_options() from public,anon;
grant execute on function public.sskr_event_place_options() to authenticated;

-- Retire the parallel GPS run API; retain existing records for a separately approved reset.
revoke execute on function public.sskr_field_tests(text,uuid,jsonb,uuid,bigint) from service_role;
